        | cbn [sc_denot]; ev_xs; cbn [edenot]; unfold b8w; rewrite ?br_eq, ?br_ne, ?br_ltu, ?br_geu by lia; bool_lia
        | eapply sc_rd_byte;
          [ rewrite (adenot_Z E _ (wa_words w)); [reflexivity | cbn [a_base]; pm_evx H w HE | lia]
          | eassumption
          | ev_xs; reflexivity ] ].

Section Hdr2.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Variable LINV : mem -> Prop.
  Hypothesis LINV_frame : forall m m' W, LINV m -> munch W m m' -> wmono asegs m m' ->
    Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) W -> LINV m'.

  Definition hdr_good_K (w : pmwA H) s LB LBs c F fc (Q : config -> Prop) : Prop :=
    forall msF1 mo1 m1 R1 (e : Z), (e = 0 \/ e = 1) -> as_AKREL H s (mkCfg msF1 mo1) ->
       as_VIS H s msF1 = MS R1 F (Z_to_bv 64 0xee168) fc None m1 (seg_rom asegs) -> rfull R1 ->
       PMXA H LINV w s LB LBs m1 mo1 (set_scalA c (c_widx c) (c_icount c) e e) [OB_BINARY] TBL_EDFD8 FTBL_EDFD8 ->
       regs_tbl w R1 RT_EDFD8 -> PropExec.getr R1 3%bv = wa_gp w -> PropExec.getr R1 4%bv = wa_tp w ->
       wa_words w <> 0 -> 4 < wa_n w ->
       as_SR H Q (mkCfg msF1 mo1).

  Lemma pm_hdr_b_le : forall (w : pmwA H) s LB LBs m mo c msF R F fc (Q : config -> Prop) (b0 b1 b2 b3 : byte),
    pmw_okA H w -> PMXA H LINV w s LB LBs m mo c [OB_BINARY] TBL_ED90C [] ->
    as_AKREL H s (mkCfg msF mo) -> as_VIS H s msF = MS R F (Z_to_bv 64 0xeda9c) fc None m (seg_rom asegs) -> rfull R ->
    regs_tbl w R RT_ED90C -> PropExec.getr R 3%bv = wa_gp w -> PropExec.getr R 4%bv = wa_tp w ->
    wa_words w <> 0 -> 4 < wa_n w ->
    rdn asegs m (Z_to_bv 64 (wa_words w + 0)) 1 = Some [b0] -> rdn asegs m (Z_to_bv 64 (wa_words w + 1)) 1 = Some [b1] ->
    rdn asegs m (Z_to_bv 64 (wa_words w + 2)) 1 = Some [b2] -> rdn asegs m (Z_to_bv 64 (wa_words w + 3)) 1 = Some [b3] ->
    bv_unsigned b0 = 3 -> bv_unsigned b1 = 2 -> bv_unsigned b2 = 35 -> bv_unsigned b3 = 7 ->
    hdr_good_K w s LB LBs c F fc Q ->
    as_SR H Q (mkCfg msF mo).
Proof.
